contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient) public payable {
        // Ensure the caller has at least 1 wei, funding it generously if needed.
        require(caller.balance >= 1 wei, "caller unfunded");

        // Fund c with a non-zero balance. The test contract must be the owner.
        require(msg.sender == c.owner(), "test must be owner");
        payable(address(c)).transfer(address(this).balance);

        uint256 balBefore = address(c).balance;
        require(balBefore > 0, "c must hold ether");
        uint256 recBefore = recipient.balance;

        // Only the owner can withdraw; record whether the deciding call reverts.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: because only the owner can execute withdrawAll, and the
        // test contract is the owner, the call always succeeds and moves c's
        // entire balance to the recipient.
        assert(!reverted && address(c).balance == 0 && recipient.balance == recBefore + balBefore);
    }

    receive() external payable {}
}

